// Legendre's formula: exponent of prime p in M!
long long exponentInFactorial(long long M, long long p) {
    long long exp = 0;
    long long power = p;
    while (power <= M) {
        exp += M / power;
        // Avoid overflow when multiplying
        if (power > M / p) break;
        power *= p;
    }
    return exp;
}

