map<long long, int> factorize(long long n) {
    map<long long, int> factors;
    for (long long p = 2; p * p <= n; p++) {
        while (n % p == 0) {
            factors[p]++;
            n /= p;
        }
    }
    if (n > 1) factors[n]++;
    return factors;
}

// Legendre's formula: sum floor(m / p^k) for k >= 1
long long legendres(long long m, long long p) {
    long long sum = 0;
    long long pk = p;
    while (pk <= m) {
        sum += m / pk;
        if (pk > m / p) break; // prevent overflow
        pk *= p;
    }
    return sum;
}

