/* Convert a digit character in base up to 36 */
static int val(char c) {
    if ('0' <= c && c <= '9') return c - '0';
    if ('A' <= c && c <= 'Z') return c - 'A' + 10;
    if ('a' <= c && c <= 'z') return c - 'a' + 10;
    return -1;
}

/* Convert string s in base base to unsigned long long */
static ull parse_base(const char *s, int base) {
    ull x = 0;
    for (int i = 0; s[i]; ++i) {
        int d = val(s[i]);
        x = x * (ull)base + (ull)d;
    }
    return x;
}

/* exponent of prime p in n! */
static ull vp_factorial(ull n, ull p) {
    ull res = 0;
    while (n) {
        n /= p;
        res += n;
    }
    return res;
}

