                    n /= p;
                }
            }
            if (n > 1) factors.merge(n, 1, Integer::sum);

            // For each prime factor, compute Legendre's formula
            BigInteger result = null;
            for (Map.Entry<Integer, Integer> e : factors.entrySet()) {
                BigInteger p = BigInteger.valueOf(e.getKey());
                int a = e.getValue();

                // v_p(M!) = sum floor(M/p^k)
