public class Main {
    static class FastScanner {
        private final BufferedReader br;
        private StringTokenizer st;

        FastScanner(InputStream is) {
            br = new BufferedReader(new InputStreamReader(is));
        }

        String next() throws IOException {
            while (st == null || !st.hasMoreTokens()) {
                String line = br.readLine();
                if (line == null) return null;
                st = new StringTokenizer(line);
            }
            return st.nextToken();
        }
    }

    static class PrimePower {
        long prime;
        int exp;

        PrimePower(long prime, int exp) {
            this.prime = prime;
            this.exp = exp;
        }
    }

    static List<PrimePower> factorize(int n) {
        List<PrimePower> res = new ArrayList<>();
        for (int p = 2; p * p <= n; p++) {
            if (n % p == 0) {
                int cnt = 0;
                while (n % p == 0) {
                    n /= p;
                    cnt++;
                }
                res.add(new PrimePower(p, cnt));
            }
        }
        if (n > 1) res.add(new PrimePower(n, 1));
        return res;
    }

    static BigInteger countExponentInFactorial(BigInteger m, long p) {
        BigInteger bp = BigInteger.valueOf(p);
        BigInteger cur = m;
        BigInteger sum = BigInteger.ZERO;
        while (cur.signum() > 0) {
            cur = cur.divide(bp);
            sum = sum.add(cur);
        }
        return sum;
    }

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner(System.in);
        StringBuilder out = new StringBuilder();

        while (true) {
            String ns = fs.next();
            String ms = fs.next();
            if (ns == null || ms == null) break;

            if (ns.equals("0") && ms.equals("0")) break;

            int base = Integer.parseInt(ns);
            BigInteger m = new BigInteger(ms, base);

            if (m.signum() == 0) {
                out.append(0).append('\n');
                continue;
            }

            List<PrimePower> factors = factorize(base);
            BigInteger ans = null;

            for (PrimePower pp : factors) {
                BigInteger expInFact = countExponentInFactorial(m, pp.prime);
                BigInteger zerosByThisPrime = expInFact.divide(BigInteger.valueOf(pp.exp));
                if (ans == null || zerosByThisPrime.compareTo(ans) < 0) {
                    ans = zerosByThisPrime;
                }
            }

            out.append(ans).append('\n');
        }

        System.out.print(out.toString());
    }
}
